function table(deps, limit) {
  const rows = deps.slice(0, limit).map((d, i2) => [
    String(i2 + 1),
    d.name,
    d.currentVersion,
    d.risk.latestVersion ?? "?",
    String(d.score),
    String(d.risk.vulnerabilities.length),
    d.risk.deprecated ? "yes" : "",
    d.dev ? "dev" : ""
  ]);
  const head = ["#", "dependency", "installed", "latest", "score", "vulns", "deprecated", ""];
  const widths = head.map((h2, c3) => Math.max(h2.length, ...rows.map((r) => (r[c3] ?? "").length)));
  const line = (r) => r.map((v, c3) => v.padEnd(widths[c3] ?? 0)).join("  ").trimEnd();
  return [line(head), ...rows.map(line)].join("\n");
}
function report(outcome, json2) {
  const { ctx, findings, plan, capsule, recommended, error: error62 } = outcome;
  if (json2) {
    process.stdout.write(
      JSON.stringify(
        {
          runId: ctx.runId,
          runDir: ctx.runDir,
          recommended: recommended?.name,
          dependencies: findings?.dependencies.map((d) => ({
            name: d.name,
            score: d.score,
            rationale: d.rationale
          })),
          plan: plan && {
            dependency: plan.dependency,
            strategy: plan.strategy,
            target: plan.target,
            feasible: plan.feasible,
            confidence: plan.confidence
          },
          verdict: capsule?.capsule.verdict,
          branch: capsule?.capsule.branch,
          error: error62
        },
        null,
        2
      ) + "\n"
    );
    return;
  }
  const out = [];
  if (findings && !plan) {
    out.push(table(findings.dependencies, 15));
    if (recommended)
      out.push(
        "",
        `Recommended: ${recommended.name} (score ${recommended.score})${recommended.rationale ? ` - ${recommended.rationale}` : ""}`
      );
  }
  if (plan)
    out.push(
      `Plan: ${plan.strategy} ${plan.dependency}@${plan.fromVersion} -> ${plan.target.name}@${plan.target.version} (confidence ${plan.confidence}, feasible ${plan.feasible})`,
      `Usage sites: ${plan.usage.length}; concerns: ${plan.concerns.map((c3) => c3.kind).join(" -> ")}`
    );
  if (capsule)
    out.push(
      `Verdict: ${capsule.capsule.verdict}`,
      `Branch: ${capsule.capsule.branch ?? "none"}`,
      `Capsule: ${ctx.runDir}/capsule.md`
    );
  if (error62) out.push(`Error: ${error62}`);
  out.push(`Run directory: ${ctx.runDir}`);
  process.stdout.write(out.join("\n") + "\n");
}
